DROP TABLE IF EXISTS analise_planos_referencias_normam;
CREATE TABLE IF NOT EXISTS analise_planos_referencias_normam (
  id char(36) NOT NULL,
  categoria varchar(100) NOT NULL,
  norma varchar(50) NOT NULL DEFAULT 'NORMAM-202',
  item_norma varchar(120) NULL,
  referencia_normativa text NOT NULL,
  titulo varchar(255) NOT NULL,
  descricao_padrao text NOT NULL,
  ativo tinyint(1) NOT NULL DEFAULT 1,
  ordem int unsigned NOT NULL DEFAULT 0,
  criado_por char(36) NULL,
  criado_em datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  atualizado_em datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_normam_categoria (categoria, ativo),
  FULLTEXT KEY idx_normam_busca (titulo)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Adicionar coluna categoria em analise_planos_exigencias se não existir
SET @col_exists = (SELECT COUNT(*) FROM information_schema.COLUMNS 
                   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'analise_planos_exigencias' AND COLUMN_NAME = 'categoria');
SET @sql = IF(@col_exists = 0, 'ALTER TABLE analise_planos_exigencias ADD COLUMN categoria varchar(100) NOT NULL DEFAULT \'GERAL\' AFTER item_id', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

